'use strict';
// AI: below section was generated by an AI
// Tests for virtualdev/device.js and server.js (node tmp_device/test.js). No npm packages.
// Checks are independent of device.js where possible: expected ids come from FX.h, expected names/metadata from FX.cpp.
const fs = require('fs');
const path = require('path');
const http = require('http');
const { spawn } = require('child_process');

const REPO = path.resolve(__dirname, '..', '..', '..', 'WLED-main');
const dev = require('../device.js');
dev.stop();                               // drive frames by hand with dev.tick(t)

let pass = 0, fail = 0;
function ok(cond, msg) { if (cond) pass++; else { fail++; console.log('  FAIL ' + msg); } }
function section(s) { console.log('- ' + s); }

const fxh = fs.readFileSync(path.join(REPO, 'wled00', 'FX.h'), 'utf8');
const fxcpp = fs.readFileSync(path.join(REPO, 'wled00', 'FX.cpp'), 'utf8');
const idOf = (def) => { const m = fxh.match(new RegExp('#define\\s+' + def + '\\s+(\\d+)')); if (!m) throw new Error(def + ' missing in FX.h'); return +m[1]; };
const dataOf = (def) => { const m = fxcpp.match(new RegExp('_data_' + def + '\\[\\]\\s*PROGMEM\\s*=\\s*"((?:[^"\\\\]|\\\\.)*)"')); if (!m) throw new Error('_data_' + def + ' missing'); return m[1]; };

/* ---------------------------------------------------------------- effect list */
section('effects');
const MODE_COUNT = +fxh.match(/#define\s+MODE_COUNT\s+(\d+)/)[1];
const setup = fxcpp.slice(fxcpp.indexOf('void WS2812FX::setupEffectData()'));
const setupBody = setup.slice(0, setup.indexOf('\n}\n'));
const addLines = setupBody.split('\n').filter(l => /^\s*addEffect\(/.test(l)).length;  // commented-out lines start with //
const conds = setupBody.split('\n').filter(l => /^\s*#\s*if/.test(l)).map(l => l.trim());
const real = dev.effects.filter(n => n !== 'RSVD').length;
console.log(`  ${dev.effects.length} slots (MODE_COUNT ${MODE_COUNT}), ${real} real; setupEffectData: ${addLines} addEffect lines + Solid; conditions: ${conds.join(' | ')}`);
console.log(`  build flags seen by FX.cpp: ${dev.build.fxDefines.join(', ')}`);
ok(dev.effects.length === MODE_COUNT, 'effect slots = MODE_COUNT');
// every #if in setupEffectData is enabled in this build (2D on, GIF on, PS_DONT_REPLACE on, PS 1D/2D not disabled)
ok(real === addLines + 1, `real effects ${real} = active addEffect lines ${addLines} + Solid`);
ok(dev.fxdata.length === dev.effects.length, 'fxdata length = effects length');
const spot = {
  FX_MODE_STATIC: 'Solid', FX_MODE_BREATH: 'Breathe', FX_MODE_RAINBOW: 'Colorloop', FX_MODE_RAINBOW_CYCLE: 'Rainbow',
  FX_MODE_FIRE_2012: 'Fire 2012', FX_MODE_METEOR: 'Meteor', FX_MODE_RIPPLE: 'Ripple', FX_MODE_TWINKLEFOX: 'Twinklefox',
  FX_MODE_CANDLE: 'Candle', FX_MODE_PACIFICA: 'Pacifica', FX_MODE_AURORA: 'Aurora', FX_MODE_IMAGE: 'Image',
  FX_MODE_GRAVCENTER: 'Gravcenter', FX_MODE_2DMATRIX: 'Matrix', FX_MODE_PARTICLEVOLCANO: 'PS Volcano', FX_MODE_PARTICLEGALAXY: 'PS Galaxy',
};
for (const [def, name] of Object.entries(spot)) {
  const id = idOf(def);
  ok(dev.effects[id] === name, `${def}=${id} is "${dev.effects[id]}", expected "${name}"`);
  const d = dataOf(def);
  ok(dev.fxdata[id] === (d.includes('@') ? d.slice(d.indexOf('@') + 1) : ''), `fxdata[${id}] matches _data_${def}`);
}
console.log(`  spot-checked ${Object.keys(spot).length} ids: Breathe=${idOf('FX_MODE_BREATH')}, Fire 2012=${idOf('FX_MODE_FIRE_2012')}, PS Galaxy=${idOf('FX_MODE_PARTICLEGALAXY')}`);
ok(dev.effects.every(n => typeof n === 'string' && n.length && !n.includes('@')), 'names have no metadata');
const rsvd = dev.effects.map((n, i) => (n === 'RSVD' ? i : -1)).filter(i => i >= 0);
console.log(`  RSVD slots: ${rsvd.join(', ')}`);
ok(rsvd.every(i => dev.fxdata[i] === ''), 'RSVD slots have empty fxdata');
// 6c's effect metadata (1D effects) agrees on every id
const metaFile = path.resolve(__dirname, '..', '..', 'fxsim', 'data', 'fxmeta.json');
if (fs.existsSync(metaFile)) {
  const meta = JSON.parse(fs.readFileSync(metaFile, 'utf8')).fx;
  const bad = meta.filter(f => dev.effects[f.id] !== f.name);
  ok(bad.length === 0, 'fxmeta.json mismatches: ' + bad.map(f => f.id + ':' + f.name).join(', '));
  console.log(`  fxmeta.json: ${meta.length} effects, ${bad.length} id/name mismatches`);
}

/* ---------------------------------------------------------------- palettes */
section('palettes');
ok(dev.palettes.length === 72, 'palette count ' + dev.palettes.length);
ok(dev.palettes[0] === 'Default' && dev.palettes[6] === 'Party' && dev.palettes[71] === 'Traffic Light', 'palette names');
const p0 = dev.palx(0);
ok(p0.m === 9, 'palx m = 9 (72/8), got ' + p0.m);
const seen = {};
for (let pg = 0; pg <= p0.m; pg++) {
  const r = dev.palx(pg);
  const keys = Object.keys(r.p);
  ok(r.m === p0.m, 'm stable');
  ok(keys.length === (pg < 9 ? 8 : 0), `page ${pg} has ${keys.length} entries`);
  for (const k of keys) {
    ok(+k === pg * 8 + keys.indexOf(k), `page ${pg} key ${k} in order`);
    const a = r.p[k];
    seen[k] = true;
    if (+k >= 1 && +k <= 5) { ok(a.every(x => ['r', 'c1', 'c2', 'c3'].includes(x)), 'marker palette ' + k); continue; }
    const pos = a.map(s => s[0]);
    ok(a.every(s => Array.isArray(s) && s.length === 4 && s.every(v => Number.isInteger(v) && v >= 0 && v <= 255)), 'stops well-formed ' + k);
    ok(pos.every((v, i) => !i || v >= pos[i - 1]), 'stop positions ascending ' + k);
    if (+k <= 12) ok(a.length === 16 && pos.every((v, i) => v === i << 4), 'CRGBPalette16 stops ' + k);
    else ok(pos[pos.length - 1] === 255, 'gradient ends at 255: ' + k);
  }
}
ok(Object.keys(seen).length === 72, 'palx covers 72 ids');
ok(JSON.stringify(dev.palx(99)) === JSON.stringify(dev.palx(9)), 'page > m clamps to m');
ok(JSON.stringify(dev.palx(1).p['8'][0]) === JSON.stringify([0, 0, 0, 0]), 'Lava starts with CRGB::Black');
const demoFile = path.resolve(__dirname, '..', '..', 'fxsim', 'data', 'palettes_demo.json');
if (fs.existsSync(demoFile)) {
  const demo = JSON.parse(fs.readFileSync(demoFile, 'utf8'));
  let diff = 0;
  for (let pg = 0; pg <= 9; pg++) { const r = dev.palx(pg); for (const k in r.p) if (JSON.stringify(r.p[k]) !== JSON.stringify(demo.p[k])) diff++; }
  ok(diff === 0 && JSON.stringify(demo.names) === JSON.stringify(dev.palettes), 'palettes_demo.json differs in ' + diff);
  console.log(`  palettes_demo.json: ${diff} differences`);
}

/* ---------------------------------------------------------------- state / applyState */
section('state');
let states = 0, usermods = [];
dev.on('state', () => states++);
dev.on('usermod', (o) => usermods.push(o));
let s = dev.state();
ok(s.on === true && s.bri === 128, 'initial on, bri 128');
ok(s.seg.length === 2 && s.seg[0].start === 0 && s.seg[0].stop === 60 && s.seg[1].start === 60 && s.seg[1].stop === 120, 'two segments 0-59, 60-119');
ok(s.seg[0].n === 'LED 1' && s.seg[1].n === 'LED 2', 'segment names');
ok(s.seg[0].fx === idOf('FX_MODE_BREATH') && s.seg[1].fx === idOf('FX_MODE_RAINBOW_CYCLE'), 'initial Breathe / Rainbow');
ok(JSON.stringify(s.seg[0].col[0]) === '[255,120,0]' && JSON.stringify(s.seg[0].col[1]) === '[0,40,200]', 'orange over blue');
const keys = ['id', 'start', 'stop', 'len', 'grp', 'spc', 'of', 'on', 'frz', 'bri', 'cct', 'set', 'col', 'fx', 'sx', 'ix', 'pal', 'c1', 'c2', 'c3', 'sel', 'rev', 'mi', 'o1', 'o2', 'o3', 'si', 'm12'];
ok(keys.every(k => k in s.seg[0]), 'segment has all VDEV.md keys');
ok(['on', 'bri', 'transition', 'ps', 'pl', 'lor', 'mainseg', 'seg'].every(k => k in s), 'state has all VDEV.md keys');

// fx change with fxdef: defaults from the metadata after the last ';'
const fire = idOf('FX_MODE_FIRE_2012');
s = dev.applyState({ seg: [{ id: 0, fx: fire, fxdef: true }] });
ok(s.seg[0].fx === fire && s.seg[0].sx === 64 && s.seg[0].ix === 160 && s.seg[0].pal === 35 && s.seg[0].c2 === 128 && s.seg[0].m12 === 1,
  'Fire 2012 fxdef -> sx64 ix160 pal35 c2 128 m12 1: ' + JSON.stringify([s.seg[0].sx, s.seg[0].ix, s.seg[0].pal, s.seg[0].c2, s.seg[0].m12]));
ok(s.seg[1].fx === idOf('FX_MODE_RAINBOW_CYCLE'), 'seg 1 untouched');
// fx change without fxdef keeps the sliders
s = dev.applyState({ seg: { id: 0, fx: idOf('FX_MODE_AURORA') } });
ok(s.seg[0].sx === 64 && s.seg[0].pal === 35, 'no fxdef keeps sliders/palette');
s = dev.applyState({ seg: { id: 0, fxdef: true, fx: idOf('FX_MODE_PACIFICA') } });
ok(s.seg[0].pal === 51 && s.seg[0].sx === 128, 'Pacifica fxdef -> pal 51, sx default 128');
// "~" steps, RSVD skipped
const rs = dev.effects.indexOf('RSVD');
if (rs > 0) {
  s = dev.applyState({ seg: { id: 0, fx: rs } });
  ok(s.seg[0].fx !== rs && dev.effects[s.seg[0].fx] !== 'RSVD', 'RSVD id skipped to ' + s.seg[0].fx);
}
s = dev.applyState({ seg: { id: 0, fx: 2 } });
s = dev.applyState({ seg: { id: 0, fx: '~' } });
ok(s.seg[0].fx === 3, '"~" increments fx');
s = dev.applyState({ seg: { id: 0, fx: '~-' } });
ok(s.seg[0].fx === 2, '"~-" decrements fx');
// colours: [r,g,b] arrays, hex strings, {r,g,b} object, Kelvin, missing entries keep the old colour
s = dev.applyState({ seg: [{ id: 1, col: [[1, 2, 3], 'FF8000', { g: 99 }] }] });
ok(JSON.stringify(s.seg[1].col) === '[[1,2,3],[255,128,0],[0,99,0]]', 'col array/hex/object: ' + JSON.stringify(s.seg[1].col));
s = dev.applyState({ seg: [{ id: 1, col: [[], '00ff00'] }] });
ok(JSON.stringify(s.seg[1].col) === '[[1,2,3],[0,255,0],[0,99,0]]', 'empty array keeps colour, lower-case hex');
s = dev.applyState({ seg: [{ id: 1, col: ['bad', 2700] }] });
ok(s.seg[1].col[0][0] === 1 && s.seg[1].col[1][0] === 255 && s.seg[1].col[1][2] < 120, 'invalid hex skipped, 2700 K warm white ' + JSON.stringify(s.seg[1].col[1]));
// "t" toggles
const st0 = states;
s = dev.applyState({ on: 't' });
ok(s.on === false && s.bri === 128, 'on:"t" -> off (bri stays 128 as briLast)');
s = dev.applyState({ on: 't' });
ok(s.on === true, 'on:"t" -> on again');
s = dev.applyState({ seg: { id: 1, on: 't' } });
ok(s.seg[1].on === false, 'seg on:"t" toggles');
s = dev.applyState({ seg: { id: 1, on: 't', rev: 't' } });
ok(s.seg[1].on === true && s.seg[1].rev === true, 'seg on/rev toggled back/on');
dev.applyState({ seg: { id: 1, rev: false } });
ok(states > st0, "'state' events emitted");
// brightness, bri 0 = off, {"on":"t","bri":32}
s = dev.applyState({ bri: 200 });
ok(s.bri === 200 && s.on, 'bri 200');
s = dev.applyState({ bri: 0 });
ok(s.on === false && s.bri === 200, 'bri 0 -> off, bri reports briLast');
s = dev.applyState({ on: 't', bri: 32 });
ok(s.on === true && s.bri === 32, '{"on":"t","bri":32} turns on at 32');
s = dev.applyState({ bri: '~10' });
ok(s.bri === 42, 'bri "~10" -> 42');
dev.applyState({ bri: 128 });
// segment opacity and selection
s = dev.applyState({ seg: { id: 1, bri: 0 } });
ok(s.seg[1].on === false && s.seg[1].bri === 255, 'seg bri 0 -> off, opacity kept');
s = dev.applyState({ seg: { id: 1, bri: 100, on: true } });
ok(s.seg[1].on && s.seg[1].bri === 100, 'seg bri 100');
s = dev.applyState({ seg: { sx: 77 } });   // no id: every selected segment
ok(s.seg[0].sx === 77 && s.seg[1].sx === 77, 'seg object without id applies to selected segments');
s = dev.applyState({ seg: [{ id: 1, sel: false }] });
s = dev.applyState({ seg: { ix: 11 } });
ok(s.seg[0].ix === 11 && s.seg[1].ix !== 11, 'unselected segment untouched');
dev.applyState({ seg: [{ id: 1, sel: true, bri: 255 }] });
// usermod key
dev.applyState({ HomeGadgets: { relay: 0, on: true, k: 'x' } });
ok(usermods.length === 1 && usermods[0].relay === 0, "'usermod' event carries the HomeGadgets object");

/* ---------------------------------------------------------------- pixels */
section('pixels');
const seg0 = (px) => Array.from(px.subarray(0, 60));
const same = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
let frames = 0;
dev.on('frame', () => frames++);
dev.applyState({ on: true, bri: 128, seg: [{ id: 0, fx: idOf('FX_MODE_BREATH'), fxdef: true, col: [[255, 0, 0], [0, 0, 255]] }, { id: 1, fx: 0, col: [[10, 20, 30]] }] });
let t = 5000;
const snaps = [];
for (let k = 0; k < 120; k++) { dev.tick(t); t += 24; if (k % 20 === 0) snaps.push(seg0(dev.pixels())); }
ok(frames >= 120, "'frame' event per tick");
ok(new Set(snaps.map(x => x.join())).size > 1, 'Breathe pixels change over time');
const solidA = Array.from(dev.pixels().subarray(60, 120));
dev.tick(t + 1000);
const solidB = Array.from(dev.pixels().subarray(60, 120));
ok(same(solidA, solidB) && solidA.every(v => v === 0x0A141E), 'Solid is constant and equals colour 1 (0x0A141E)');
ok(dev.pixels().length === 120 && dev.pixels() instanceof Uint32Array, 'pixels() Uint32Array(120)');
dev.applyState({ seg: { id: 1, bri: 128 } });
dev.tick(t + 1100);
const half = dev.pixels()[60];
ok(((half >>> 16) & 255) === 5 && ((half >>> 8) & 255) === 10 && (half & 255) === 15, 'segment opacity 128 halves the colour: ' + half.toString(16));
dev.applyState({ seg: { id: 1, bri: 255 } });
dev.applyState({ seg: { id: 1, on: false } });
dev.tick(t + 1200);
ok(Array.from(dev.pixels().subarray(60, 120)).every(v => v === 0), 'off segment is black');
ok(Array.from(dev.pixels().subarray(0, 60)).some(v => v !== 0), 'other segment still lit');
dev.applyState({ on: false });
dev.tick(t + 1300);
ok(dev.pixels().every(v => v === 0), 'global off is black');
dev.applyState({ on: true, seg: { id: 1, on: true } });
// reverse and grouping on a 3-colour gradient-free check: "i" individual pixels + reverse
dev.applyState({ seg: { id: 1, i: [0, [255, 0, 0], 1, [0, 255, 0]] } });
dev.tick(t + 1400);
let px = dev.pixels();
ok(px[60] === 0xFF0000 && px[61] === 0x00FF00 && px[62] === 0, '"i" sets raw pixels and freezes');
dev.applyState({ seg: { id: 1, rev: true } });
dev.tick(t + 1450);
px = dev.pixels();
ok(px[119] === 0xFF0000 && px[118] === 0x00FF00, 'reverse maps pixel 0 to the last LED');
dev.applyState({ seg: { id: 1, rev: false, frz: false, fx: 0, grp: 2 } });
ok(dev.state().seg[1].grp === 2, 'grouping set');
dev.applyState({ seg: { id: 1, grp: 1 } });

/* ---------------------------------------------------------------- engine coverage */
section('fxsim');
const fi = dev.fxsimInfo();
console.log(`  engine: ${fi.dir}`);
console.log(`  FXS implements ${fi.implemented} of ${fi.total} listed effects; ${fi.fallback.length} fall back (palette scroll):`);
console.log('   ' + fi.fallback.join(', '));
ok(fi.implemented >= 140, 'fxsim implements the 1D effects');
// every implemented effect renders without throwing on the device path
let threw = 0;
const warnOrig = console.warn; console.warn = (m) => { if (/threw/.test(m)) threw++; };
for (let id = 0; id < dev.effects.length; id++) {
  if (dev.effects[id] === 'RSVD') continue;
  dev.applyState({ seg: { id: 0, fx: id, fxdef: true } });
  for (let k = 0; k < 5; k++) dev.tick(t += 24);
}
console.warn = warnOrig;
ok(threw === 0, threw + ' effects threw on the device path');

/* ---------------------------------------------------------------- server.js */
section('server');
function get(port, p) {
  return new Promise((res) => {
    http.get({ host: '127.0.0.1', port, path: p }, (r) => { let b = ''; r.on('data', d => b += d); r.on('end', () => res({ status: r.statusCode, body: b })); })
      .on('error', (e) => res({ status: 0, body: e.message }));
  });
}
function upgrade(port, p) {
  return new Promise((res) => {
    const req = http.request({ host: '127.0.0.1', port, path: p, headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': 'dGhlIHNhbXBsZSBub25jZQ==' } });
    req.on('upgrade', (r, sock) => { sock.destroy(); res(101); });
    req.on('response', (r) => { r.resume(); res(r.statusCode); });
    req.on('error', () => res(0));
    req.end();
  });
}
(async () => {
  const port = 18000 + Math.floor(Math.random() * 1000);
  const child = spawn(process.execPath, [path.join(__dirname, '..', 'server.js'), '--port', String(port)], { stdio: ['ignore', 'pipe', 'pipe'] });
  let out = '';
  child.stdout.on('data', d => out += d); child.stderr.on('data', d => out += d);
  for (let i = 0; i < 50 && !/Home Gadgets:/.test(out); i++) await new Promise(r => setTimeout(r, 100));
  const info = await get(port, '/__info');
  let j = null; try { j = JSON.parse(info.body); } catch (_) { /* */ }
  ok(info.status === 200 && j && j.virtual === true && j.port === port && j.fxsim && j.fxsim.total === fi.total, '/__info JSON');
  if (j) console.log(`  /__info: mirrors ${j.mirrors}, modules ${JSON.stringify(j.modules)}, fxsim ${j.fxsim.implemented}/${j.fxsim.total}`);
  const r404 = await get(port, '/definitely-not-here');
  ok(r404.status === 404, 'unknown path -> 404');
  const u = await upgrade(port, '/nope');
  ok(u === 404, 'unknown upgrade -> 404 (' + u + ')');
  child.kill();
  console.log('  server log:\n    ' + out.trim().split('\n').join('\n    '));
  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})();
// AI: end
